148	/**
149	 * Files that represent the governance or "constitution" of the repository
150	 * and should be write-protected in any sandbox.
151	 */
152	export const GOVERNANCE_FILES = [
153	  { path: '.gitignore', isDirectory: false },
154	  { path: '.geminiignore', isDirectory: false },
155	  { path: '.git', isDirectory: true },
156	] as const;
