158	/**
159	 * Files that contain sensitive secrets or credentials and should be
160	 * completely hidden (deny read/write) in any sandbox.
161	 */
162	export const SECRET_FILES = [
163	  { pattern: '.env' },
164	  { pattern: '.env.*' },
165	] as const;
