167	/**
168	 * Checks if a given file name matches any of the secret file patterns.
169	 */
170	export function isSecretFile(fileName: string): boolean {
171	  return SECRET_FILES.some((s) => {
172	    if (s.pattern.endsWith('*')) {
173	      const prefix = s.pattern.slice(0, -1);
174	      return fileName.startsWith(prefix);
175	    }
176	    return fileName === s.pattern;
177	  });
178	}
