180	/**
181	 * Returns arguments for the Linux 'find' command to locate secret files.
182	 */
183	export function getSecretFileFindArgs(): string[] {
184	  const args: string[] = ['('];
185	  SECRET_FILES.forEach((s, i) => {
186	    if (i > 0) args.push('-o');
187	    args.push('-name', s.pattern);
188	  });
189	  args.push(')');
190	  return args;
191	}
