195	 * Default is shallow scan (depth 1) for performance.
196	 */
197	export async function findSecretFiles(
198	  baseDir: string,
199	  maxDepth = 1,
200	): Promise<string[]> {
201	  const secrets: string[] = [];
202	  const skipDirs = new Set([
203	    'node_modules',
204	    '.git',
205	    '.venv',
206	    '__pycache__',
207	    'dist',
208	    'build',
209	    '.next',
210	    '.idea',
211	    '.vscode',
212	  ]);
213	
214	  async function walk(dir: string, depth: number) {
215	    if (depth > maxDepth) return;
216	    try {
217	      const entries = await fs.readdir(dir, { withFileTypes: true });
218	      for (const entry of entries) {
219	        const fullPath = path.join(dir, entry.name);
220	        if (entry.isDirectory()) {
221	          if (!skipDirs.has(entry.name)) {
222	            await walk(fullPath, depth + 1);
223	          }
224	        } else if (entry.isFile()) {
225	          if (isSecretFile(entry.name)) {
226	            secrets.push(fullPath);
227	          }
228	        }
229	      }
230	    } catch {
231	      // Ignore read errors
232	    }
233	  }
234	
235	  await walk(baseDir, 1);
236	  return secrets;
237	}
