19	/**
20	 * Creates a sandbox manager based on the provided settings.
21	 */
22	export function createSandboxManager(
23	  sandbox: SandboxConfig | undefined,
24	  options: GlobalSandboxOptions,
25	  approvalMode?: string,
26	): SandboxManager {
27	  if (approvalMode === 'yolo') {
28	    return new NoopSandboxManager();
29	  }
30	
31	  if (!options.modeConfig && options.policyManager && approvalMode) {
32	    options.modeConfig = options.policyManager.getModeConfig(approvalMode);
33	  }
34	
35	  if (sandbox?.enabled) {
36	    if (os.platform() === 'win32') {
37	      return new WindowsSandboxManager(options);
38	    } else if (os.platform() === 'linux') {
39	      return new LinuxSandboxManager(options);
40	    } else if (os.platform() === 'darwin') {
41	      return new MacOsSandboxManager(options);
42	    }
43	    return new LocalSandboxManager();
44	  }
45	
46	  return new NoopSandboxManager();
47	}
