117	function touch(filePath: string, isDirectory: boolean) {
118	  try {
119	    // If it exists (even as a broken symlink), do nothing
120	    if (fs.lstatSync(filePath)) return;
121	  } catch {
122	    // Ignore ENOENT
123	  }
124	
125	  if (isDirectory) {
126	    fs.mkdirSync(filePath, { recursive: true });
127	  } else {
128	    fs.mkdirSync(dirname(filePath), { recursive: true });
129	    fs.closeSync(fs.openSync(filePath, 'a'));
130	  }
131	}
