74	async function runCommand(command: SandboxedCommand) {
75	  try {
76	    const { stdout, stderr } = await promisify(execFile)(
77	      command.program,
78	      command.args,
79	      {
80	        cwd: command.cwd,
81	        env: command.env,
82	        encoding: 'utf-8',
83	      },
84	    );
85	    return { status: 0, stdout, stderr };
86	  } catch (error: unknown) {
87	    const err = error as { code?: number; stdout?: string; stderr?: string };
88	    return {
89	      status: err.code ?? 1,
90	      stdout: err.stdout ?? '',
91	      stderr: err.stderr ?? '',
92	    };
93	  }
94	}
