96	/**
97	 * Determines if the system has the necessary binaries to run the sandbox.
98	 * Throws an error if a supported platform is missing its required tools.
99	 */
100	function ensureSandboxAvailable(): boolean {
101	  const platform = os.platform();
102	
103	  if (platform === 'win32') {
104	    // Windows sandboxing relies on icacls, which is a core system utility and
105	    // always available.
106	    return true;
107	  }
108	
109	  if (platform === 'darwin') {
110	    if (fs.existsSync('/usr/bin/sandbox-exec')) {
111	      try {
112	        execSync('sandbox-exec -p "(version 1)(allow default)" echo test', {
113	          stdio: 'ignore',
114	        });
115	        return true;
116	      } catch {
117	        // eslint-disable-next-line no-console
118	        console.warn(
119	          'sandbox-exec is present but cannot be used (likely running inside a sandbox already). Skipping sandbox tests.',
120	        );
121	        return false;
122	      }
123	    }
124	    throw new Error(
125	      'Sandboxing tests on macOS require /usr/bin/sandbox-exec to be present.',
126	    );
127	  }
128	
129	  if (platform === 'linux') {
130	    try {
131	      execSync('which bwrap', { stdio: 'ignore' });
132	      return true;
133	    } catch {
134	      throw new Error(
135	        'Sandboxing tests on Linux require bubblewrap (bwrap) to be installed.',
136	      );
137	    }
138	  }
139	
140	  return false;
141	}
